package cse.oop2.hotelreservation.common;
import java.io.Serializable;
public class RoomStatusInfo implements Serializable { public static final String STATE_AVAILABLE="AVAILABLE", STATE_CLEANING="CLEANING", STATE_CONSTRUCTION="CONSTRUCTION"; private String roomId,state,price,note,ownerEmail; private boolean booked; public RoomStatusInfo(String roomId,String state,String price,String note,boolean booked,String ownerEmail){this.roomId=roomId;this.state=state;this.price=price;this.note=note;this.booked=booked;this.ownerEmail=ownerEmail;} public String getRoomId(){return roomId;} public String getState(){return state;} public String getPrice(){return price;} public String getNote(){return note;} public boolean isBooked(){return booked;} public String getOwnerEmail(){return ownerEmail;} public void setState(String v){state=v;} public void setPrice(String v){price=v;} public void setNote(String v){note=v;} public void setBooked(boolean v){booked=v;} public void setOwnerEmail(String v){ownerEmail=v;} }
